const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define Pantanal region (Brazil)
  const pantanal = ee.Geometry.Polygon([
    [[-60.5, -19], [-56, -19], [-56, -22], [-60.5, -22], [-60.5, -19]]
  ]);

  // MODIS Aqua fire data (MCD14DL - daily fire detection)
  const modisCollection = ee.ImageCollection('MODIS/006/MYD14DL');

  // 1. Get June 11, 2024 data
  const june11_2024 = modisCollection
    .filterDate('2024-06-11', '2024-06-12')
    .filterBounds(pantanal);

  const count_2024 = june11_2024.size().getInfo();

  if (count_2024 === 0) {
    console.log("No MODIS Aqua data for June 11, 2024");
    console.log("<answer>C1</answer>");
    return;
  }

  // Extract fire detections for June 11, 2024
  const fireDetections_2024 = june11_2024
    .map(img => img.select(['Confidence']).gte(30)) // Confidence >= 30
    .reduce(ee.Reducer.sum());

  const fireCount_2024 = fireDetections_2024.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: pantanal,
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  const val_2024 = fireCount_2024['Confidence'] || 0;
  console.log(`June 11, 2024 Fire Detections: ${val_2024}`);

  // 2. Get max fire detections for any June (2000-2023)
  let maxFireCount = 0;
  let maxYear = null;

  for (let year = 2000; year <= 2023; year++) {
    const startDate = `${year}-06-01`;
    const endDate = `${year}-06-30`;

    const juneData = modisCollection
      .filterDate(startDate, endDate)
      .filterBounds(pantanal);

    const yearCount = juneData.size().getInfo();

    if (yearCount === 0) {
      console.log(`June ${year}: No data (C1)`);
      continue;
    }

    const fireDetections = juneData
      .map(img => img.select(['Confidence']).gte(30))
      .reduce(ee.Reducer.sum());

    const fireResult = fireDetections.reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: pantanal,
      scale: 1000,
      maxPixels: 1e9
    }).getInfo();

    const fireVal = fireResult['Confidence'] || 0;

    if (fireVal > maxFireCount) {
      maxFireCount = fireVal;
      maxYear = year;
    }
  }

  if (maxFireCount === null || maxFireCount === undefined) {
    console.log("Failed to calculate historical max");
    console.log("<answer>C3</answer>");
    return;
  }

  console.log(`Historical Max (June 2000-2023): ${maxFireCount} in June ${maxYear}`);
  console.log(`June 11, 2024 vs Max: ${val_2024} vs ${maxFireCount}`);

  if (val_2024 > maxFireCount) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
